// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    ERCDDAToken c;
    function setUp() public {
        c = new ERCDDAToken(100, "Test", "TST");
    }

    function testFuzz_property(uint256 burnAmount) public {
        uint256 ownerBalance = c.balanceOf(c.owner());
        vm.assume(burnAmount <= ownerBalance);
        vm.assume(burnAmount > 0);

        uint256 supplyBefore = c.totalSupply();
        uint256 totalBalBefore = c.balanceOf(c.owner()) + c.balanceOf(address(0));

        vm.prank(c.owner());
        c.burn(burnAmount);

        uint256 supplyAfter = c.totalSupply();
        uint256 totalBalAfter = c.balanceOf(c.owner()) + c.balanceOf(address(0));

        assertTrue(supplyAfter == totalBalAfter);
    }
}
